   C("Was the film good? — No, it ___.", ["wasn't", "weren't", "didn't"], "wasn't", "No, it wasn't."),
   F("We ___ late. We were on time.", "weren't", "Заперечення — weren't.", "Отрицание — weren't.", acc=["were not"]),
