   X("He were at work.", "He was at work.", "He → was."),
   B("How was your trip", "How → was → your trip?"),
   T("Учора було сонячно.", "Вчера было солнечно.", "It was sunny yesterday.", "It was…", acc=["Yesterday it was sunny.", "Yesterday was sunny."]),
